for rn in (1,3,4):
 d=root/f"round-{rn}"; fs=sorted(d.glob("seat-*.json")); ids=[]; bad=[]
 for f in fs:
  try: ids.append(json.loads(f.read_text()).get("seat"))
  except Exception as e: bad.append((f.name,str(e)))
 print(f"round-{rn}: seat_json={len(fs)} seat_ids={len([x for x in ids if x])} bad_json={bad}")
 if rn==1:
  with (d/"census.tsv").open() as h: print(f"round-1 rows={sum(1 for _ in csv.DictReader(h,delimiter=chr(9)))}")
 if rn==3:
  with (d/"operator-approval-list.tsv").open() as h: print(f"round-3 approval_data_rows={sum(1 for _ in csv.DictReader(h,delimiter=chr(9)))}")
print("round-2 directory:", (root/"round-2").exists())'

